  var start=new MethodNode(ACC_PRIVATE,"task9$startMileage","()V",null,null);var s=new LabelNode();var end=new LabelNode();var h=new LabelNode();var done=new LabelNode();start.tryCatchBlocks.add(new TryCatchBlockNode(s,end,h,"java/lang/Exception"));var v=start.instructions;v.add(s);v.add(new VarInsnNode(ALOAD,0));v.add(new TypeInsnNode(NEW,bridge));v.add(new InsnNode(DUP));v.add(new VarInsnNode(ALOAD,0));v.add(new MethodInsnNode(INVOKESPECIAL,bridge,"<init>","(L"+owner+";)V",false));v.add(new FieldInsnNode(PUTFIELD,owner,"mileage","L"+bridge+";"));v.add(end);v.add(new JumpInsnNode(GOTO,done));v.add(h);v.add(new FrameNode(F_SAME1,0,null,1,new Object[]{"java/lang/Exception"}));v.add(new VarInsnNode(ASTORE,1));v.add(new VarInsnNode(ALOAD,0));v.add(new MethodInsnNode(INVOKEVIRTUAL,owner,"getLogger","()Ljava/util/logging/Logger;",false));v.add(new LdcInsnNode("Mileage shop initialization failed; existing services remain available"));v.add(new MethodInsnNode(INVOKEVIRTUAL,"java/util/logging/Logger","severe","(Ljava/lang/String;)V",false));v.add(done);v.add(new FrameNode(F_SAME,0,null,0,null));v.add(new InsnNode(RETURN));start.maxLocals=2;c.methods.add(start);
  var stop=new MethodNode(ACC_PRIVATE,"task9$stopMileage","()V",null,null);var exit=new LabelNode();v=stop.instructions;v.add(new VarInsnNode(ALOAD,0));v.add(new FieldInsnNode(GETFIELD,owner,"mileage","L"+bridge+";"));v.add(new JumpInsnNode(IFNULL,exit));v.add(new VarInsnNode(ALOAD,0));v.add(new FieldInsnNode(GETFIELD,owner,"mileage","L"+bridge+";"));v.add(new MethodInsnNode(INVOKEVIRTUAL,bridge,"close","()V",false));v.add(new VarInsnNode(ALOAD,0));v.add(new InsnNode(ACONST_NULL));v.add(new FieldInsnNode(PUTFIELD,owner,"mileage","L"+bridge+";"));v.add(exit);v.add(new FrameNode(F_SAME,0,null,0,null));v.add(new InsnNode(RETURN));stop.maxLocals=1;c.methods.add(stop);
